# 2D tiling: y0 = yindex % 3 varies within block -> stride-3 scatter on stores
@triton.autotune(configs=[Config({'XBLOCK':512,'YBLOCK':1}), Config({'XBLOCK':512,'YBLOCK':2}), ...], key=['ynumel','xnumel'])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK, XBLOCK):
    yindex = pid1*YBLOCK + arange(0,YBLOCK)[:,None]  # ynumel=30
    xindex = pid0*XBLOCK + arange(0,XBLOCK)[None,:]  # xnumel=50176
    y0 = yindex % 3   # varies within block when YBLOCK>1
    y1 = yindex // 3
    tmp = tl.load(in_ptr + (xindex + 50176*yindex), ...)
    tl.store(out_ptr + (y0 + 3*xindex + 150528*y1), tmp, ...)  # stride-3!
